 public static T Parse<T>(string value){if(value==null||value.Length>64000)throw new Exception("Phản hồi AI rỗng hoặc quá dài.");int start=value.IndexOf('{');if(start<0)throw new Exception("AI chưa trả JSON hợp lệ.");bool quoted=false,escape=false;int depth=0,end=-1;for(int i=start;i<value.Length;i++){char c=value[i];if(quoted){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='"')quoted=false;}else if(c=='"')quoted=true;else if(c=='{')depth++;else if(c=='}'&&--depth==0){end=i+1;break;}}if(end<0)throw new Exception("Phản hồi AI chưa hoàn chỉnh.");using(var stream=new MemoryStream(Encoding.UTF8.GetBytes(value.Substring(start,end-start))))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(stream);}
